page.css:
:root{
  --gallery:#F4F1EB; --onyx:#151515; --onyx-l:#242422; --travertine:#CFC1B2;
  --oxide:#A6513D; --oxide-d:#8E4331; --alum:#A8A8A5; --parchment:#E7E0D7;
  --line:#DCD4C7; --muted:#6C6862; --white:#FFFFFF;
  --gut:46px; --r:0px;
  --shadow:0 1px 2px rgba(21,21,21,.04), 0 14px 34px rgba(21,21,21,.07);
  --shadow-lg:0 2px 6px rgba(21,21,21,.05), 0 30px 70px rgba(21,21,21,.13);
  --sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --mono:"PT Mono","SFMono-Regular",Menlo,Consolas,monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--gallery);color:var(--onyx);font-family:var(--sans);
  font-size:15.5px;line-height:1.75;font-weight:400;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--sans);font-weight:300;line-height:1.1;margin:0;letter-spacing:-.01em}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1320px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:74px;padding-bottom:74px}
/* PT Mono for labels, filters, category labels and technical detail (§2) */
.lbl{font-family:var(--mono);font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;
  color:var(--oxide);margin-bottom:20px;display:block}
.lbl-a{color:var(--alum)}
.h2{font-size:clamp(28px,3.6vw,46px);text-transform:uppercase;letter-spacing:-.005em}
.h2-lc{text-transform:none;font-size:clamp(26px,3.2vw,40px)}
.lead{color:var(--muted);font-size:15.5px;max-width:58ch;line-height:1.85}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:46px}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--parchment)}
.simg{display:block;width:100%;height:auto;aspect-ratio:1/1;object-fit:cover;background:var(--parchment)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(20px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--mono);font-weight:400;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;
  padding:18px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--oxide);color:#fff}
.btn-1:hover{background:var(--oxide-d)}
.btn-2{background:transparent;color:var(--onyx);border-color:var(--travertine)}
.btn-2:hover{border-color:var(--onyx);background:var(--parchment)}
.btn-d{background:var(--onyx);color:#fff}
.btn-d:hover{background:var(--onyx-l)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.4)}
.btn-o:hover{background:rgba(255,255,255,.1);border-color:#fff}
.btn-w{background:#fff;color:var(--onyx);border-color:#fff}
.btn-w:hover{background:var(--parchment)}
.btn-sm{padding:13px 22px;font-size:9.5px}
.btn-lg{padding:20px 42px;font-size:11px}
.lnk{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:inline-flex;align-items:center;gap:8px}
.lnk::after{content:"→";transition:transform .22s ease;display:inline-block}
a:hover .lnk::after{transform:translateX(5px)}
.lnk-w{color:var(--travertine)}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(244,241,235,.96);
  backdrop-filter:saturate(140%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:26px;min-height:82px}
.brand{flex-shrink:0;font-family:var(--sans);font-weight:300;font-size:20px;letter-spacing:.24em;
  color:var(--onyx);white-space:nowrap;line-height:1;text-transform:uppercase}
.nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:7px;padding:10px 13px;
  font-family:var(--mono);font-size:10px;letter-spacing:.19em;text-transform:uppercase;
  color:var(--onyx);cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--oxide)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.5}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:270px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 10px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:10px 16px;font-size:14px;color:var(--onyx);transition:.18s ease}
.menu a:hover{background:var(--parchment);color:var(--oxide)}
.menu .mh{display:block;padding:4px 16px 10px;font-family:var(--mono);font-size:9.5px;
  letter-spacing:.22em;text-transform:uppercase;color:var(--alum)}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{background:var(--parchment);border-bottom:1px solid var(--line)}
.hero-grid{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:0;align-items:stretch}
.hero-txt{padding:112px 66px 112px 0;display:flex;flex-direction:column;justify-content:center;min-width:0}
h1{font-size:clamp(38px,5.4vw,68px);font-weight:300;letter-spacing:-.015em;text-transform:uppercase;
  margin-bottom:24px;line-height:1.02}
.hero-lead{font-size:16px;color:var(--muted);max-width:44ch;margin-bottom:38px;line-height:1.85}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:36px}
.ticks{display:flex;flex-wrap:wrap;gap:10px 26px}
.tick{display:flex;align-items:center;gap:9px;font-family:var(--mono);font-size:9.5px;
  letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.tick svg{width:13px;height:13px;flex-shrink:0}
.hero-img{position:relative;min-width:0}
.hero-img img{display:block;width:100%;height:100%;min-height:600px;object-fit:cover}
.swap-tag{position:absolute;right:14px;bottom:14px;background:rgba(21,21,21,.66);color:#fff;
  font-family:var(--mono);font-size:9px;letter-spacing:.16em;text-transform:uppercase;padding:7px 14px}

/* ---------- occasion tiles ---------- */
.tiles{display:grid;gap:22px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease}
.tile:hover{border-color:var(--travertine)}
.tile .tb{padding:18px 20px 22px}
.tile b{display:block;font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.18em;
  text-transform:uppercase;margin-bottom:8px}
.tile span{display:block;font-size:13.5px;color:var(--muted);line-height:1.7}
.tile .lnk{margin-top:14px}

/* ---------- elements (dark band) ---------- */
.dark{background:var(--onyx);color:#fff}
.dark .h2{color:#fff}
.dark .lead{color:rgba(255,255,255,.6)}
.el-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.el{min-width:0;display:block;border:1px solid rgba(255,255,255,.16);padding:22px 22px 24px;
  transition:background .22s ease,border-color .22s ease}
.el:hover{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.34)}
.el .num{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--oxide);
  display:block;margin-bottom:14px}
.el b{display:block;font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.16em;
  text-transform:uppercase;color:#fff;margin-bottom:8px}
.el span{display:block;font-size:13px;color:rgba(255,255,255,.56);line-height:1.7}
.el .lnk{margin-top:14px;color:var(--travertine)}

/* ---------- notice band ---------- */
.notice{background:var(--onyx);color:#fff;padding:52px 48px}
.notice h3{font-size:clamp(22px,2.8vw,32px);text-transform:uppercase;font-weight:300;
  letter-spacing:-.005em;margin-bottom:16px;color:#fff}
.notice p{color:rgba(255,255,255,.62);font-size:14.5px;line-height:1.85;max-width:74ch}

/* ---------- styling split rows ---------- */
.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:44px;align-items:center;
  margin-bottom:34px}
.split:last-child{margin-bottom:0}
.split.flip .sp-img{order:2}
.sp-img{min-width:0}
.sp-txt{min-width:0}
.sp-txt h3{font-family:var(--mono);font-weight:400;font-size:12px;letter-spacing:.2em;
  text-transform:uppercase;margin-bottom:12px}
.sp-txt p{font-size:14.5px;color:var(--muted);line-height:1.8;margin-bottom:18px}

/* ---------- journal ---------- */
.jr{min-width:0;display:block;background:var(--white);border:1px solid var(--line);padding:26px 26px 28px;
  transition:border-color .25s ease}
.jr:hover{border-color:var(--travertine)}
.jr .k{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:block;margin-bottom:16px}
.jr h3{font-size:19px;font-weight:400;line-height:1.35;margin-bottom:10px}
.jr p{font-size:13.5px;color:var(--muted);line-height:1.7}
.jr .lnk{margin-top:18px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.18em;
  text-transform:uppercase;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.8px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--oxide);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 17px;font-family:var(--mono);font-size:10px;
  letter-spacing:.12em;text-transform:uppercase;background:var(--white);transition:.18s ease}
.pop a:hover{border-color:var(--oxide);color:var(--oxide)}

/* ---------- brief (5-step, pure CSS) ---------- */
.brief{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(0,.68fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.brief-main{padding:52px 50px;min-width:0}
.brief-side{background:var(--parchment);border-left:1px solid var(--line);padding:0;min-width:0}
.bs-img img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover}
.bs-in{padding:34px 34px 38px}
.bs-in h3{font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.2em;
  text-transform:uppercase;margin-bottom:18px}
.bs-in li{display:flex;gap:11px;font-size:13.4px;color:var(--muted);line-height:1.7;
  padding:7px 0;min-width:0}
.bs-in li svg{width:14px;height:14px;flex-shrink:0;margin-top:5px}
.mem{background:var(--onyx);color:rgba(255,255,255,.66);padding:26px 30px}
.mem .lbl{color:var(--alum);margin-bottom:10px}
.mem h4{font-size:19px;font-weight:400;color:#fff;margin-bottom:12px}
.mem p{font-size:12.8px;line-height:1.8}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:36px}
.stepper label{display:flex;align-items:center;gap:9px;min-width:0;cursor:pointer;padding-top:13px;
  border-top:1px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--mono);font-weight:400;font-size:10px;color:var(--alum);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-family:var(--mono);font-size:9px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--alum);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:20px}
#se1:checked ~ .panes .p1,#se2:checked ~ .panes .p2,#se3:checked ~ .panes .p3,
#se4:checked ~ .panes .p4,#se5:checked ~ .panes .p5{display:grid}
#se1:checked ~ .stepper label:nth-child(1),#se2:checked ~ .stepper label:nth-child(2),
#se3:checked ~ .stepper label:nth-child(3),#se4:checked ~ .stepper label:nth-child(4),
#se5:checked ~ .stepper label:nth-child(5){border-top-color:var(--oxide);border-top-width:2px}
#se1:checked ~ .stepper label:nth-child(1) b,#se1:checked ~ .stepper label:nth-child(1) span,
#se2:checked ~ .stepper label:nth-child(2) b,#se2:checked ~ .stepper label:nth-child(2) span,
#se3:checked ~ .stepper label:nth-child(3) b,#se3:checked ~ .stepper label:nth-child(3) span,
#se4:checked ~ .stepper label:nth-child(4) b,#se4:checked ~ .stepper label:nth-child(4) span,
#se5:checked ~ .stepper label:nth-child(5) b,#se5:checked ~ .stepper label:nth-child(5) span{color:var(--oxide)}
.field{min-width:0}
.field>label{display:block;font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--onyx);background:var(--gallery);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--oxide);
  box-shadow:0 0 0 3px rgba(166,81,61,.16)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:96px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A29D96;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:12.5px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:8px}
.picks label{display:inline-flex;align-items:center;font-family:var(--mono);font-size:10px;
  letter-spacing:.1em;text-transform:uppercase;padding:10px 15px;border:1px solid var(--line);
  background:var(--gallery);cursor:pointer;transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--travertine)}
.picks label:has(input:checked){background:var(--onyx);border-color:var(--onyx);color:#fff}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.6px;color:var(--muted);
  line-height:1.7;cursor:pointer;min-width:0}
.consent input{width:16px;height:16px;flex-shrink:0;margin-top:3px;accent-color:var(--oxide);appearance:auto}
.fnote{font-family:var(--mono);font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;
  color:var(--alum);line-height:1.8;text-align:center}
.opt-lbl{font-family:var(--mono);font-size:8.5px;letter-spacing:.14em;color:var(--oxide);
  border:1px solid var(--line);padding:2px 7px;margin-left:7px}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-size:19px;font-weight:400;transition:color .2s ease}
.faq summary:hover{color:var(--oxide)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:36px;
  background:var(--oxide);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:14px;height:1px}
.faq summary::before{width:1px;height:14px;right:18px;top:29px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:14.6px;color:var(--muted);line-height:1.9}

/* ---------- footer ---------- */
footer{background:var(--onyx);color:rgba(255,255,255,.56);padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid rgba(255,255,255,.13)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:16px}
.f-brand .tag{font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:block;margin-bottom:20px}
.f-brand p{font-size:13.4px;line-height:1.85;max-width:34ch;margin-bottom:24px}
.f-col{min-width:0}
.f-col h3{font-family:var(--mono);font-weight:400;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13.2px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--travertine)}
.f-seo{padding:26px 0;border-bottom:1px solid rgba(255,255,255,.13);font-size:17px;
  font-weight:300;color:#fff;text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 34px;font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;
  text-transform:uppercase;color:rgba(255,255,255,.4)}
.f-bot a:hover{color:var(--travertine)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:20px;height:20px;flex-shrink:0;display:block}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:70px;height:70px;border:1px solid var(--travertine);display:grid;place-items:center;
  margin:0 auto 30px}
.ty-mark svg{width:30px;height:30px}
.ty h1{font-size:clamp(30px,4.2vw,48px);margin-bottom:22px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:24px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--oxide);
  flex-shrink:0;padding-top:5px}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-weight:400;font-size:19px;margin-bottom:6px}
.ty-next em{font-style:normal;font-size:14px;color:var(--muted);line-height:1.8}
.note{margin-top:36px;font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--muted);
  border:1px dashed var(--travertine);padding:16px 22px;line-height:1.9;text-transform:uppercase}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 10px;font-size:9.4px;letter-spacing:.15em}
  .hdr{gap:18px} }
@media (max-width:1240px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0}
  .burger span{display:block;width:20px;height:1px;background:var(--onyx);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--onyx)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:82px;left:0;right:0;bottom:0;margin:0;background:var(--gallery);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:11px;letter-spacing:.2em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:15px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr)}
  .hero-txt{padding:66px 0 58px}
  .hero-img img{min-height:420px}
  .t4,.el-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .split,.split.flip{grid-template-columns:minmax(0,1fr);gap:22px;margin-bottom:44px}
  .split.flip .sp-img{order:0}
  .brief{grid-template-columns:minmax(0,1fr)}
  .brief-main{padding:40px 32px}
  .brief-side{border-left:0;border-top:1px solid var(--line)}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
  .notice{padding:40px 30px}
}
@media (max-width:768px){
  :root{--gut:22px}
  .sec{padding-top:64px;padding-bottom:64px}
  .sec-t{padding-top:50px;padding-bottom:50px}
  .nav{top:72px}
  .hdr{min-height:72px}
  .brand{font-size:15px;letter-spacing:.18em}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(244,241,235,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 14px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 8px;font-size:9px;letter-spacing:.1em}
  footer{padding-bottom:78px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.el-grid,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .brief-main{padding:30px 20px}
  .bs-in,.mem{padding:26px 20px}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:17px;padding-right:42px}
}

:root{
  --gallery:#F4F1EB; --onyx:#151515; --onyx-l:#242422; --travertine:#CFC1B2;
  --oxide:#A6513D; --oxide-d:#8E4331; --alum:#A8A8A5; --parchment:#E7E0D7;
  --line:#DCD4C7; --muted:#6C6862; --white:#FFFFFF;
  --gut:46px; --r:0px;
  --shadow:0 1px 2px rgba(21,21,21,.04), 0 14px 34px rgba(21,21,21,.07);
  --shadow-lg:0 2px 6px rgba(21,21,21,.05), 0 30px 70px rgba(21,21,21,.13);
  --sans:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;
  --mono:"PT Mono","SFMono-Regular",Menlo,Consolas,monospace;
}
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%;scroll-behavior:smooth}
body{margin:0;background:var(--gallery);color:var(--onyx);font-family:var(--sans);
  font-size:15.5px;line-height:1.75;font-weight:400;-webkit-font-smoothing:antialiased}
h1,h2,h3,h4{font-family:var(--sans);font-weight:300;line-height:1.1;margin:0;letter-spacing:-.01em}
p{margin:0}
a{color:inherit;text-decoration:none}
img{max-width:100%}
ul,ol{margin:0;padding:0;list-style:none}

.wrap{width:100%;max-width:1320px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.sec{padding-top:104px;padding-bottom:104px}
.sec-t{padding-top:74px;padding-bottom:74px}
/* PT Mono for labels, filters, category labels and technical detail (§2) */
.lbl{font-family:var(--mono);font-size:10.5px;letter-spacing:.22em;text-transform:uppercase;
  color:var(--oxide);margin-bottom:20px;display:block}
.lbl-a{color:var(--alum)}
.h2{font-size:clamp(28px,3.6vw,46px);text-transform:uppercase;letter-spacing:-.005em}
.h2-lc{text-transform:none;font-size:clamp(26px,3.2vw,40px)}
.lead{color:var(--muted);font-size:15.5px;max-width:58ch;line-height:1.85}
.ctr{text-align:center}
.ctr .lead{margin-left:auto;margin-right:auto}
.sec-head{margin-bottom:46px}

/* ---------- images ---------- */
.cimg{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover;background:var(--parchment)}
.simg{display:block;width:100%;height:auto;aspect-ratio:1/1;object-fit:cover;background:var(--parchment)}

/* ---------- reveal (pure CSS, JS-free) ---------- */
.rv{animation:rvIn .9s both}
.rv2{animation-delay:.09s}.rv3{animation-delay:.18s}.rv4{animation-delay:.27s}
@keyframes rvIn{from{opacity:.55;transform:translateY(20px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.rv{animation:none}}

/* ---------- buttons ---------- */
.btn{display:inline-flex;align-items:center;justify-content:center;gap:10px;
  font-family:var(--mono);font-weight:400;font-size:10.5px;letter-spacing:.2em;text-transform:uppercase;
  padding:18px 34px;border-radius:var(--r);border:1px solid transparent;cursor:pointer;
  transition:background .22s ease,color .22s ease,border-color .22s ease;white-space:nowrap}
.btn-1{background:var(--oxide);color:#fff}
.btn-1:hover{background:var(--oxide-d)}
.btn-2{background:transparent;color:var(--onyx);border-color:var(--travertine)}
.btn-2:hover{border-color:var(--onyx);background:var(--parchment)}
.btn-d{background:var(--onyx);color:#fff}
.btn-d:hover{background:var(--onyx-l)}
.btn-o{background:transparent;color:#fff;border-color:rgba(255,255,255,.4)}
.btn-o:hover{background:rgba(255,255,255,.1);border-color:#fff}
.btn-w{background:#fff;color:var(--onyx);border-color:#fff}
.btn-w:hover{background:var(--parchment)}
.btn-sm{padding:13px 22px;font-size:9.5px}
.btn-lg{padding:20px 42px;font-size:11px}
.lnk{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:inline-flex;align-items:center;gap:8px}
.lnk::after{content:"→";transition:transform .22s ease;display:inline-block}
a:hover .lnk::after{transform:translateX(5px)}
.lnk-w{color:var(--travertine)}

/* ---------- header ---------- */
header{position:sticky;top:0;z-index:60;background:rgba(244,241,235,.96);
  backdrop-filter:saturate(140%) blur(12px);border-bottom:1px solid var(--line)}
.hdr{display:flex;align-items:center;gap:26px;min-height:82px}
.brand{flex-shrink:0;font-family:var(--sans);font-weight:300;font-size:20px;letter-spacing:.24em;
  color:var(--onyx);white-space:nowrap;line-height:1;text-transform:uppercase}
.nav{margin-left:auto;display:flex;align-items:center;gap:4px}
.nav>li{position:relative}
.nav a.top,.nav .drop-lbl{display:flex;align-items:center;gap:7px;padding:10px 13px;
  font-family:var(--mono);font-size:10px;letter-spacing:.19em;text-transform:uppercase;
  color:var(--onyx);cursor:pointer;white-space:nowrap;transition:color .2s ease}
.nav a.top:hover,.nav .drop-lbl:hover{color:var(--oxide)}
.nav-cta{display:none}
.nav .caret{width:8px;height:8px;flex-shrink:0;opacity:.5}
.menu{position:absolute;top:calc(100% + 16px);left:-10px;min-width:270px;background:var(--white);
  border:1px solid var(--line);box-shadow:var(--shadow-lg);padding:16px 10px;
  opacity:0;visibility:hidden;transform:translateY(8px);transition:.2s ease}
.nav>li:hover>.menu,.nav>li:focus-within>.menu{opacity:1;visibility:visible;transform:none}
.menu a{display:block;padding:10px 16px;font-size:14px;color:var(--onyx);transition:.18s ease}
.menu a:hover{background:var(--parchment);color:var(--oxide)}
.menu .mh{display:block;padding:4px 16px 10px;font-family:var(--mono);font-size:9.5px;
  letter-spacing:.22em;text-transform:uppercase;color:var(--alum)}
.hdr-act{display:flex;align-items:center;flex-shrink:0}
.burger,.mtoggle,.dtoggle{display:none}

/* ---------- hero ---------- */
.hero{background:var(--parchment);border-bottom:1px solid var(--line)}
.hero-grid{display:grid;grid-template-columns:minmax(0,.92fr) minmax(0,1.08fr);gap:0;align-items:stretch}
.hero-txt{padding:112px 66px 112px 0;display:flex;flex-direction:column;justify-content:center;min-width:0}
h1{font-size:clamp(38px,5.4vw,68px);font-weight:300;letter-spacing:-.015em;text-transform:uppercase;
  margin-bottom:24px;line-height:1.02}
.hero-lead{font-size:16px;color:var(--muted);max-width:44ch;margin-bottom:38px;line-height:1.85}
.hero-cta{display:flex;flex-wrap:wrap;gap:14px;margin-bottom:36px}
.ticks{display:flex;flex-wrap:wrap;gap:10px 26px}
.tick{display:flex;align-items:center;gap:9px;font-family:var(--mono);font-size:9.5px;
  letter-spacing:.16em;text-transform:uppercase;color:var(--muted)}
.tick svg{width:13px;height:13px;flex-shrink:0}
.hero-img{position:relative;min-width:0}
.hero-img img{display:block;width:100%;height:100%;min-height:600px;object-fit:cover}
.swap-tag{position:absolute;right:14px;bottom:14px;background:rgba(21,21,21,.66);color:#fff;
  font-family:var(--mono);font-size:9px;letter-spacing:.16em;text-transform:uppercase;padding:7px 14px}

/* ---------- occasion tiles ---------- */
.tiles{display:grid;gap:22px}
.t4{grid-template-columns:repeat(4,minmax(0,1fr))}
.t3{grid-template-columns:repeat(3,minmax(0,1fr))}
.t2{grid-template-columns:repeat(2,minmax(0,1fr))}
.tile{min-width:0;display:block;background:var(--white);border:1px solid var(--line);
  transition:border-color .25s ease}
.tile:hover{border-color:var(--travertine)}
.tile .tb{padding:18px 20px 22px}
.tile b{display:block;font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.18em;
  text-transform:uppercase;margin-bottom:8px}
.tile span{display:block;font-size:13.5px;color:var(--muted);line-height:1.7}
.tile .lnk{margin-top:14px}

/* ---------- elements (dark band) ---------- */
.dark{background:var(--onyx);color:#fff}
.dark .h2{color:#fff}
.dark .lead{color:rgba(255,255,255,.6)}
.el-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}
.el{min-width:0;display:block;border:1px solid rgba(255,255,255,.16);padding:22px 22px 24px;
  transition:background .22s ease,border-color .22s ease}
.el:hover{background:rgba(255,255,255,.05);border-color:rgba(255,255,255,.34)}
.el .num{font-family:var(--mono);font-size:9.5px;letter-spacing:.18em;color:var(--oxide);
  display:block;margin-bottom:14px}
.el b{display:block;font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.16em;
  text-transform:uppercase;color:#fff;margin-bottom:8px}
.el span{display:block;font-size:13px;color:rgba(255,255,255,.56);line-height:1.7}
.el .lnk{margin-top:14px;color:var(--travertine)}

/* ---------- notice band ---------- */
.notice{background:var(--onyx);color:#fff;padding:52px 48px}
.notice h3{font-size:clamp(22px,2.8vw,32px);text-transform:uppercase;font-weight:300;
  letter-spacing:-.005em;margin-bottom:16px;color:#fff}
.notice p{color:rgba(255,255,255,.62);font-size:14.5px;line-height:1.85;max-width:74ch}

/* ---------- styling split rows ---------- */
.split{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:44px;align-items:center;
  margin-bottom:34px}
.split:last-child{margin-bottom:0}
.split.flip .sp-img{order:2}
.sp-img{min-width:0}
.sp-txt{min-width:0}
.sp-txt h3{font-family:var(--mono);font-weight:400;font-size:12px;letter-spacing:.2em;
  text-transform:uppercase;margin-bottom:12px}
.sp-txt p{font-size:14.5px;color:var(--muted);line-height:1.8;margin-bottom:18px}

/* ---------- journal ---------- */
.jr{min-width:0;display:block;background:var(--white);border:1px solid var(--line);padding:26px 26px 28px;
  transition:border-color .25s ease}
.jr:hover{border-color:var(--travertine)}
.jr .k{font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:block;margin-bottom:16px}
.jr h3{font-size:19px;font-weight:400;line-height:1.35;margin-bottom:10px}
.jr p{font-size:13.5px;color:var(--muted);line-height:1.7}
.jr .lnk{margin-top:18px}

/* ---------- locations ---------- */
.loc-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:34px}
.loc-col{min-width:0}
.loc-col h3{font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.18em;
  text-transform:uppercase;margin-bottom:14px}
.loc-col li{border-bottom:1px solid var(--line)}
.loc-col a{display:block;font-size:13.8px;padding:9px 0;overflow-wrap:anywhere;transition:.18s ease}
.loc-col a:hover{color:var(--oxide);padding-left:6px}
.pop{display:flex;flex-wrap:wrap;gap:9px;margin-top:16px}
.pop a{border:1px solid var(--line);padding:9px 17px;font-family:var(--mono);font-size:10px;
  letter-spacing:.12em;text-transform:uppercase;background:var(--white);transition:.18s ease}
.pop a:hover{border-color:var(--oxide);color:var(--oxide)}

/* ---------- brief (5-step, pure CSS) ---------- */
.brief{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(0,.68fr);gap:0;
  background:var(--white);border:1px solid var(--line)}
.brief-main{padding:52px 50px;min-width:0}
.brief-side{background:var(--parchment);border-left:1px solid var(--line);padding:0;min-width:0}
.bs-img img{display:block;width:100%;height:auto;aspect-ratio:4/3;object-fit:cover}
.bs-in{padding:34px 34px 38px}
.bs-in h3{font-family:var(--mono);font-weight:400;font-size:11px;letter-spacing:.2em;
  text-transform:uppercase;margin-bottom:18px}
.bs-in li{display:flex;gap:11px;font-size:13.4px;color:var(--muted);line-height:1.7;
  padding:7px 0;min-width:0}
.bs-in li svg{width:14px;height:14px;flex-shrink:0;margin-top:5px}
.mem{background:var(--onyx);color:rgba(255,255,255,.66);padding:26px 30px}
.mem .lbl{color:var(--alum);margin-bottom:10px}
.mem h4{font-size:19px;font-weight:400;color:#fff;margin-bottom:12px}
.mem p{font-size:12.8px;line-height:1.8}
.stp{position:absolute;opacity:0;pointer-events:none;width:0;height:0}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.stepper{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:8px;margin-bottom:36px}
.stepper label{display:flex;align-items:center;gap:9px;min-width:0;cursor:pointer;padding-top:13px;
  border-top:1px solid var(--line);transition:border-color .25s ease}
.stepper b{font-family:var(--mono);font-weight:400;font-size:10px;color:var(--alum);flex-shrink:0;
  transition:color .25s ease}
.stepper span{font-family:var(--mono);font-size:9px;letter-spacing:.14em;text-transform:uppercase;
  color:var(--alum);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;transition:color .25s ease}
.pane{display:none;gap:20px}
#se1:checked ~ .panes .p1,#se2:checked ~ .panes .p2,#se3:checked ~ .panes .p3,
#se4:checked ~ .panes .p4,#se5:checked ~ .panes .p5{display:grid}
#se1:checked ~ .stepper label:nth-child(1),#se2:checked ~ .stepper label:nth-child(2),
#se3:checked ~ .stepper label:nth-child(3),#se4:checked ~ .stepper label:nth-child(4),
#se5:checked ~ .stepper label:nth-child(5){border-top-color:var(--oxide);border-top-width:2px}
#se1:checked ~ .stepper label:nth-child(1) b,#se1:checked ~ .stepper label:nth-child(1) span,
#se2:checked ~ .stepper label:nth-child(2) b,#se2:checked ~ .stepper label:nth-child(2) span,
#se3:checked ~ .stepper label:nth-child(3) b,#se3:checked ~ .stepper label:nth-child(3) span,
#se4:checked ~ .stepper label:nth-child(4) b,#se4:checked ~ .stepper label:nth-child(4) span,
#se5:checked ~ .stepper label:nth-child(5) b,#se5:checked ~ .stepper label:nth-child(5) span{color:var(--oxide)}
.field{min-width:0}
.field>label{display:block;font-family:var(--mono);font-size:9.5px;letter-spacing:.2em;
  text-transform:uppercase;color:var(--muted);margin-bottom:9px}
input,select,textarea{min-width:0;width:100%;border:1px solid var(--line);border-radius:var(--r);
  padding:14px 15px;font-size:14.5px;font-family:var(--sans);color:var(--onyx);background:var(--gallery);
  appearance:none;transition:border-color .2s ease,box-shadow .2s ease}
input:focus,select:focus,textarea:focus{outline:none;border-color:var(--oxide);
  box-shadow:0 0 0 3px rgba(166,81,61,.16)}
select{background-image:linear-gradient(45deg,transparent 50%,var(--muted) 50%),
  linear-gradient(135deg,var(--muted) 50%,transparent 50%);
  background-position:calc(100% - 20px) 21px,calc(100% - 14px) 21px;
  background-size:6px 6px,6px 6px;background-repeat:no-repeat;padding-right:42px}
textarea{resize:vertical;min-height:96px;line-height:1.6}
input::placeholder,textarea::placeholder{color:#A29D96;font-size:13.5px}
input[type=file]{padding:11px 14px;font-size:12.5px}
.frow{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:14px}
.frow>*{min-width:0}
.picks{display:flex;flex-wrap:wrap;gap:8px}
.picks label{display:inline-flex;align-items:center;font-family:var(--mono);font-size:10px;
  letter-spacing:.1em;text-transform:uppercase;padding:10px 15px;border:1px solid var(--line);
  background:var(--gallery);cursor:pointer;transition:.18s ease}
.picks input{position:absolute;opacity:0;width:0;height:0}
.picks label:hover{border-color:var(--travertine)}
.picks label:has(input:checked){background:var(--onyx);border-color:var(--onyx);color:#fff}
.btnrow{display:flex;gap:12px;flex-wrap:wrap}
.btnrow>*{flex:1 1 0;min-width:0}
.btnrow .btn-2{flex:0 0 auto;padding-left:26px;padding-right:26px}
.nextb{cursor:pointer}
.consent{display:flex;gap:12px;align-items:flex-start;font-size:12.6px;color:var(--muted);
  line-height:1.7;cursor:pointer;min-width:0}
.consent input{width:16px;height:16px;flex-shrink:0;margin-top:3px;accent-color:var(--oxide);appearance:auto}
.fnote{font-family:var(--mono);font-size:9.5px;letter-spacing:.12em;text-transform:uppercase;
  color:var(--alum);line-height:1.8;text-align:center}
.opt-lbl{font-family:var(--mono);font-size:8.5px;letter-spacing:.14em;color:var(--oxide);
  border:1px solid var(--line);padding:2px 7px;margin-left:7px}

/* ---------- faq ---------- */
.faq{max-width:900px;margin:0 auto;border-top:1px solid var(--line)}
.faq details{border-bottom:1px solid var(--line)}
.faq summary{cursor:pointer;list-style:none;padding:26px 58px 26px 0;position:relative;
  font-size:19px;font-weight:400;transition:color .2s ease}
.faq summary:hover{color:var(--oxide)}
.faq summary::-webkit-details-marker{display:none}
.faq summary::after,.faq summary::before{content:"";position:absolute;right:12px;top:36px;
  background:var(--oxide);transition:transform .25s ease,opacity .25s ease}
.faq summary::after{width:14px;height:1px}
.faq summary::before{width:1px;height:14px;right:18px;top:29px}
.faq details[open] summary::before{opacity:0;transform:rotate(90deg)}
.faq .ans{padding:0 60px 28px 0;font-size:14.6px;color:var(--muted);line-height:1.9}

/* ---------- footer ---------- */
footer{background:var(--onyx);color:rgba(255,255,255,.56);padding-top:84px}
.f-top{display:grid;grid-template-columns:minmax(0,1.5fr) repeat(4,minmax(0,1fr));gap:40px;
  padding-bottom:54px;border-bottom:1px solid rgba(255,255,255,.13)}
.f-brand{min-width:0}
.f-brand .brand{color:#fff;display:inline-block;margin-bottom:16px}
.f-brand .tag{font-family:var(--mono);font-size:10px;letter-spacing:.2em;text-transform:uppercase;
  color:var(--oxide);display:block;margin-bottom:20px}
.f-brand p{font-size:13.4px;line-height:1.85;max-width:34ch;margin-bottom:24px}
.f-col{min-width:0}
.f-col h3{font-family:var(--mono);font-weight:400;font-size:9.5px;letter-spacing:.22em;
  text-transform:uppercase;color:#fff;margin-bottom:18px}
.f-col li{margin-bottom:11px}
.f-col a{font-size:13.2px;overflow-wrap:anywhere;transition:.18s ease}
.f-col a:hover{color:var(--travertine)}
.f-seo{padding:26px 0;border-bottom:1px solid rgba(255,255,255,.13);font-size:17px;
  font-weight:300;color:#fff;text-align:center}
.f-bot{display:flex;flex-wrap:wrap;gap:16px 30px;align-items:center;justify-content:space-between;
  padding:26px 0 34px;font-family:var(--mono);font-size:9.5px;letter-spacing:.1em;
  text-transform:uppercase;color:rgba(255,255,255,.4)}
.f-bot a:hover{color:var(--travertine)}
.credit{display:inline-flex;align-items:center;gap:9px;white-space:nowrap}
.credit img{width:20px;height:20px;flex-shrink:0;display:block}

/* ---------- sticky mobile ---------- */
.sticky{display:none}

/* ---------- thank you ---------- */
.ty{max-width:720px;margin:0 auto;text-align:center}
.ty-mark{width:70px;height:70px;border:1px solid var(--travertine);display:grid;place-items:center;
  margin:0 auto 30px}
.ty-mark svg{width:30px;height:30px}
.ty h1{font-size:clamp(30px,4.2vw,48px);margin-bottom:22px}
.ty>.lead{margin:0 auto 40px}
.ty-next{border-top:1px solid var(--line);text-align:left;margin-bottom:40px}
.ty-next li{display:flex;gap:24px;padding:26px 0;border-bottom:1px solid var(--line);min-width:0}
.ty-next b{font-family:var(--mono);font-size:10px;letter-spacing:.18em;color:var(--oxide);
  flex-shrink:0;padding-top:5px}
.ty-next span{display:block;min-width:0}
.ty-next strong{display:block;font-weight:400;font-size:19px;margin-bottom:6px}
.ty-next em{font-style:normal;font-size:14px;color:var(--muted);line-height:1.8}
.note{margin-top:36px;font-family:var(--mono);font-size:10px;letter-spacing:.08em;color:var(--muted);
  border:1px dashed var(--travertine);padding:16px 22px;line-height:1.9;text-transform:uppercase}
.cta-row{display:flex;flex-wrap:wrap;gap:14px;justify-content:center}

/* ================= responsive ================= */
@media (max-width:1500px){ .nav a.top,.nav .drop-lbl{padding:10px 10px;font-size:9.4px;letter-spacing:.15em}
  .hdr{gap:18px} }
@media (max-width:1240px){
  .burger{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--line);
    background:var(--white);cursor:pointer;margin-left:auto;flex-shrink:0}
  .burger span{display:block;width:20px;height:1px;background:var(--onyx);position:relative}
  .burger span::before,.burger span::after{content:"";position:absolute;left:0;width:20px;height:1px;background:var(--onyx)}
  .burger span::before{top:-6px}.burger span::after{top:6px}
  .hdr-act{display:none}
  .nav{position:fixed;top:82px;left:0;right:0;bottom:0;margin:0;background:var(--gallery);
    display:block;overflow-y:auto;padding:22px var(--gut) 48px;clip-path:inset(0 0 0 100%);
    pointer-events:none;opacity:0;transition:clip-path .34s ease,opacity .28s ease;z-index:70}
  .mtoggle:checked ~ .nav{clip-path:inset(0 0 0 0);pointer-events:auto;opacity:1}
  .nav>li{border-bottom:1px solid var(--line)}
  .nav a.top,.nav .drop-lbl{padding:18px 2px;font-size:11px;letter-spacing:.2em;justify-content:space-between}
  .nav .caret{width:11px;height:11px;transition:transform .22s ease}
  .menu{position:static;opacity:1;visibility:visible;transform:none;box-shadow:none;border:0;
    padding:0 0 16px;min-width:0;max-height:0;overflow:hidden;transition:max-height .34s ease;background:transparent}
  .dtoggle:checked + .drop-lbl + .menu{max-height:900px}
  .dtoggle:checked + .drop-lbl .caret{transform:rotate(180deg)}
  .menu a{padding:9px 0;font-size:15px;color:var(--muted)}
  .menu .mh{padding-left:0}
  .nav-cta{display:flex!important;flex-direction:column;gap:12px;padding-top:26px;border:0!important}
  .nav-cta .btn{width:100%}
}
@media (max-width:1100px){
  .hero-grid{grid-template-columns:minmax(0,1fr)}
  .hero-txt{padding:66px 0 58px}
  .hero-img img{min-height:420px}
  .t4,.el-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .split,.split.flip{grid-template-columns:minmax(0,1fr);gap:22px;margin-bottom:44px}
  .split.flip .sp-img{order:0}
  .brief{grid-template-columns:minmax(0,1fr)}
  .brief-main{padding:40px 32px}
  .brief-side{border-left:0;border-top:1px solid var(--line)}
  .loc-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
  .f-top{grid-template-columns:repeat(3,minmax(0,1fr))}
  .f-brand{grid-column:1/-1}
  .notice{padding:40px 30px}
}
@media (max-width:768px){
  :root{--gut:22px}
  .sec{padding-top:64px;padding-bottom:64px}
  .sec-t{padding-top:50px;padding-bottom:50px}
  .nav{top:72px}
  .hdr{min-height:72px}
  .brand{font-size:15px;letter-spacing:.18em}
  .stepper span{display:none}
  .stepper label{justify-content:center;padding-top:11px}
  .sticky{display:flex;position:fixed;left:0;right:0;bottom:0;z-index:80;gap:10px;
    background:rgba(244,241,235,.97);backdrop-filter:blur(12px);border-top:1px solid var(--line);
    padding:11px 14px calc(11px + env(safe-area-inset-bottom))}
  .sticky .btn{flex:1 1 0;min-width:0;padding:15px 8px;font-size:9px;letter-spacing:.1em}
  footer{padding-bottom:78px}
}
@media (max-width:620px){
  .t4,.t3,.t2,.el-grid,.loc-grid,.f-top{grid-template-columns:minmax(0,1fr)}
  .frow{grid-template-columns:minmax(0,1fr)}
  .f-top{gap:30px}
}
@media (max-width:430px){
  :root{--gut:18px}
  .brief-main{padding:30px 20px}
  .bs-in,.mem{padding:26px 20px}
  .btn{white-space:normal;text-align:center;padding-left:20px;padding-right:20px;max-width:100%}
  .btnrow{flex-direction:column}
  .btnrow>*{width:100%}
  .faq summary{font-size:17px;padding-right:42px}
}
